mapper.update:
update departments_51
set leader_id  = #{leaderId},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
where dept_id  = #{deptId}
  and is_deleted = 'n'

update departments_51
set is_active  = #{isActive},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
where dept_id  = #{deptId}
  and is_deleted = 'n'

update departments_51
set is_deleted = 'y',
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
where dept_id  = #{deptId}
  and is_deleted = 'n'

update departments_51
set leader_id  = NULL,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
where leader_id = #{leaderId}
  and is_deleted = 'n'

mapper.select:
with dept_emp_counts_51 as ( select dept_id, count(*) as emp_count from employees_51 where is_deleted = 'n' group by dept_id ) select d.dept_id as deptId, d.parent_dept_id as parentDeptId, d.leader_id as leaderId, d.dept_name as deptName, p.dept_name as parentDeptName, e.name as leaderName, isnull(ec.emp_count, 0) as employeeCount, d.is_active as isActive, d.is_deleted as isDeleted, d.version as version, d.created_at as createdAt, d.created_by as createdBy from departments_51 d left join departments_51 p on d.parent_dept_id = p.dept_id and p.is_deleted = 'n' left join employees_51 e on d.leader_id = e.emp_id and e.is_deleted = 'n' left join dept_emp_counts_51 ec on d.dept_id = ec.dept_id where d.dept_id in
#{item}
and d.is_deleted = 'n'
